namespace sv_79e2bc57fb224412bbd7855a312872cd.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_79e2bc57fb224412bbd7855a312872cd.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!_submitted)
    {
        @* Step 1: Personal Info *@
        @if (_currentStep == 0)
        {
            <div class="form-step">
                <h2>Personal Information</h2>

                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="_fullName" class="form-control" />
                    @if (_showValidation && string.IsNullOrWhiteSpace(_fullName))
                    {
                        <span class="validation-error">Full name is required.</span>
                    }
                </div>

                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="_email" class="form-control" />
                    @if (_showValidation && string.IsNullOrWhiteSpace(_email))
                    {
                        <span class="validation-error">Email is required.</span>
                    }
                    else if (!string.IsNullOrEmpty(_emailError))
                    {
                        <span class="validation-error">@_emailError</span>
                    }
                </div>

                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="_phone" class="form-control" />
                    @if (_showValidation && string.IsNullOrWhiteSpace(_phone))
                    {
                        <span class="validation-error">Phone is required.</span>
                    }
                </div>

                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="_address" class="form-control" />
                    @if (_showValidation && string.IsNullOrWhiteSpace(_address))
                    {
                        <span class="validation-error">Address is required.</span>
                    }
                </div>

                <div class="form-buttons">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                        @if (_isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        }

        @* Step 2: Work History *@
        @if (_currentStep == 1)
        {
            <div class="form-step">
                <h2>Work History</h2>

                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="_workEntries[index].Company" class="form-control" />
                            @if (_showValidation && string.IsNullOrWhiteSpace(_workEntries[index].Company))
                            {
                                <span class="validation-error">Company name is required.</span>
                            }
                        </div>

                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="_workEntries[index].Title" class="form-control" />
                            @if (_showValidation && string.IsNullOrWhiteSpace(_workEntries[index].Title))
                            {
                                <span class="validation-error">Job title is required.</span>
                            }
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="_workEntries[index].StartDate" class="form-control" />
                            </div>

                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="_workEntries[index].EndDate" class="form-control"
                                       disabled="@_workEntries[index].IsCurrent" />
                            </div>
                        </div>

                        <div class="form-group">
                            <label class="checkbox-label">
                                <input type="checkbox" @bind="_workEntries[index].IsCurrent" />
                                Currently working here
                            </label>
                        </div>

                        <div class="form-group">
                            <label>Description *</label>
                            <textarea @bind="_workEntries[index].Description" class="form-control" rows="3"></textarea>
                            @if (_showValidation && string.IsNullOrWhiteSpace(_workEntries[index].Description))
                            {
                                <span class="validation-error">Description is required.</span>
                            }
                        </div>
                    </div>
                }

                <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
                </div>
            </div>
        }

        @* Step 3: References *@
        @if (_currentStep == 2)
        {
            <div class="form-step">
                <h2>References</h2>

                @for (int i = 0; i < _references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="_references[index].Name" class="form-control" />
                            @if (_showValidation && string.IsNullOrWhiteSpace(_references[index].Name))
                            {
                                <span class="validation-error">Name is required.</span>
                            }
                        </div>

                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="_references[index].Relationship" class="form-control" />
                            @if (_showValidation && string.IsNullOrWhiteSpace(_references[index].Relationship))
                            {
                                <span class="validation-error">Relationship is required.</span>
                            }
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Email *</label>
                                <input type="email" @bind="_references[index].Email" class="form-control" />
                                @if (_showValidation && string.IsNullOrWhiteSpace(_references[index].Email))
                                {
                                    <span class="validation-error">Email is required.</span>
                                }
                            </div>

                            <div class="form-group">
                                <label>Phone *</label>
                                <input type="tel" @bind="_references[index].Phone" class="form-control" />
                                @if (_showValidation && string.IsNullOrWhiteSpace(_references[index].Phone))
                                {
                                    <span class="validation-error">Phone is required.</span>
                                }
                            </div>
                        </div>
                    </div>
                }

                @if (_references.Count < 3)
                {
                    <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
                </div>
            </div>
        }

        @* Step 4: Cover Letter *@
        @if (_currentStep == 3)
        {
            <div class="form-step">
                <h2>Cover Letter</h2>

                <div class="form-group">
                    <label for="coverLetter">Write your cover letter *</label>
                    <textarea id="coverLetter" @bind="_coverLetter" @bind:event="oninput"
                              class="form-control cover-letter-textarea" rows="12"
                              maxlength="2000"></textarea>
                    <div class="character-count @(_coverLetter.Length > 2000 ? "over-limit" : "")">
                        @_coverLetter.Length / 2000 characters
                    </div>
                    @if (_showValidation && string.IsNullOrWhiteSpace(_coverLetter))
                    {
                        <span class="validation-error">Cover letter is required.</span>
                    }
                </div>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
                </div>
            </div>
        }

        @* Step 5: Review & Submit *@
        @if (_currentStep == 4)
        {
            <div class="form-step">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <div class="review-content">
                        <p><strong>Name:</strong> @_fullName</p>
                        <p><strong>Email:</strong> @_email</p>
                        <p><strong>Phone:</strong> @_phone</p>
                        <p><strong>Address:</strong> @_address</p>
                    </div>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    <div class="review-content">
                        @foreach (var entry in _workEntries)
                        {
                            <div class="review-work-entry">
                                <p><strong>@entry.Title</strong> at @entry.Company</p>
                                <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                                <p>@entry.Description</p>
                            </div>
                        }
                    </div>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    <div class="review-content">
                        @foreach (var reference in _references)
                        {
                            <div class="review-reference">
                                <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                                <p>@reference.Email | @reference.Phone</p>
                            </div>
                        }
                    </div>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn btn-link" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <div class="review-content">
                        <p class="cover-letter-preview">@_coverLetter</p>
                    </div>
                </div>

                @if (!string.IsNullOrEmpty(_submitError))
                {
                    <div class="alert alert-danger">@_submitError</div>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        @* Confirmation *@
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been successfully submitted.</p>
            <p class="application-id"><strong>Application ID:</strong> @_applicationId</p>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private int _highestCompletedStep = -1;
    private bool _showValidation = false;
    private bool _isValidating = false;
    private bool _isSubmitting = false;
    private bool _submitted = false;
    private int _applicationId;
    private string _submitError = string.Empty;
    private string _emailError = string.Empty;

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == _currentStep) return "active";
        if (IsStepCompleted(stepIndex)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int stepIndex) => stepIndex <= _highestCompletedStep;

    private void GoToStep(int stepIndex)
    {
        if (IsStepCompleted(stepIndex) || stepIndex == _currentStep)
        {
            _showValidation = false;
            _emailError = string.Empty;
            _currentStep = stepIndex;
        }
    }

    private void PreviousStep()
    {
        _showValidation = false;
        _emailError = string.Empty;
        _currentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        _showValidation = true;
        _emailError = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
            return;

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _emailError = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        AdvanceStep();
    }

    private void NextFromWorkHistory()
    {
        _showValidation = true;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                string.IsNullOrWhiteSpace(entry.Description))
                return;
        }

        AdvanceStep();
    }

    private void NextFromReferences()
    {
        _showValidation = true;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
                return;
        }

        AdvanceStep();
    }

    private void NextFromCoverLetter()
    {
        _showValidation = true;

        if (string.IsNullOrWhiteSpace(_coverLetter))
            return;

        AdvanceStep();
    }

    private void AdvanceStep()
    {
        _showValidation = false;
        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;
        _currentStep++;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _highestCompletedStep = 4;
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
    transition: all 0.3s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #999;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
